package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request supplies an email whose lower-cased form is already
 * used by another owner. Handled globally by {@link DuplicateEmailExceptionHandler}, which
 * responds 409.
 */
